747→<!-- Redirect links and searches when in dual view mode -->
748→<script>
749→document.addEventListener("DOMContentLoaded", function () {
750→  if (!window.location.pathname.startsWith("/dual")) return;
751→
752→  function getTargetPanel() {
753→    const selected = document.querySelector('input[name="targetPanel"]:checked');
754→    return selected ? selected.value : "left";
755→  }
756→
757→  function loadInPanel(panel, path) {
758→    if (!path) return;
759→    const iframe = document.getElementById(`iframe-${panel}`);
760→    if (!iframe) return;
761→    const url = path.includes("?") ? path + "&embed=1" : path + "?embed=1";
762→    iframe.src = url;
763→    const inputBox = document.querySelector(`#panel-${panel} input`);
764→    if (inputBox) inputBox.value = path;
765→    console.log(`Loaded "${url}" into panel "${panel}"`);
766→  }
767→  
768→  document.querySelectorAll(".dual-aware a[href^='/'], a.dual-aware[href^='/']").forEach(link => {
769→    link.addEventListener("click", function (e) {
770→      e.preventDefault();
771→      const path = this.getAttribute("href");
772→      loadInPanel(getTargetPanel(), path);
773→    });
774→  });
775→
776→  const idForm = document.getElementById("idsearchForm");
777→  if (idForm) {
778→    idForm.addEventListener("submit", function (e) {
779→      e.preventDefault();
780→      const input = idForm.querySelector(".idsearchTerm").value.trim();
781→      if (!input) return;
782→
783→      let path = null;
784→
785→      if (/^\d+$/.test(input)) {
786→        path = "/go_to/" + encodeURIComponent(input);
787→      } else if (/^((\d+|end)(-(\d+|end))?\s*)+(open|solved|yes|no)?$/i.test(input)) {
788→        const parts = input.split(/\s+/).filter(Boolean);
789→        path = "/range/" + parts.map(encodeURIComponent).join("/");
790→      } else {
791→        alert("Invalid input format.");
792→        return;
793→      }
794→
795→      loadInPanel(getTargetPanel(), path);
796→    });
797→  }
798→
799→  const searchForm = document.getElementById("searchForm");
800→  if (searchForm) {
801→    searchForm.addEventListener("submit", function (e) {
802→      e.preventDefault();
803→      const input = searchForm.querySelector(".searchTerm").value.trim();
804→      if (!input) return;
805→
806→      const path = "/search/" + encodeURIComponent(input);
807→      loadInPanel(getTargetPanel(), path);
808→    });
809→  }
810→});
811→</script>
